using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "MoonBathAction", menuName = "Data/Battle/Battle Actions/Moonie/MoonBath Action")]
public class MoonBathAction : ChooseDiceAction
{
	[Header("Moon Bath Specifics")]
	[SerializeField]
	private DiceTier hexDiceTier;

	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private OmenLogic targetToPurifyLogic;

	[SerializeField]
	private PlayerDice paralyzedHexDie;

	[SerializeField]
	private int paralyzedHexDieAdditionalTimes;

	[Header("Description")]
	[SerializeField]
	private Tag tagHexDie;

	[Header("Moonlight Effect")]
	[SerializeField]
	private Effect moonlightEffect;

	[Header("Debug")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	protected bool verbose;

	public PurifyAction PurifyAction => purifyAction;

	public PlayerDice ParalyzedHexDie => paralyzedHexDie;

	public int ParalyzedHexDieAdditionalTimes => paralyzedHexDieAdditionalTimes;

	public Tag TagHexDie => tagHexDie;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
		{
			if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i).Dice.DiceTier == hexDiceTier)
			{
				return true;
			}
		}
		return false;
	}

	public override bool CheckCondition(DiceInstance diceInstance)
	{
		return diceInstance.Dice.DiceTier == hexDiceTier;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		bool flag = diceList.First().Dice.DiceName == paralyzedHexDie.DiceName;
		for (int i = 0; i < diceList.Count; i++)
		{
			DiceInstance diceInstance = diceList[i];
			$"MOON BATH: Destroyed status dice {diceInstance.name}".DebugLogIfVerbose(verbose);
			ReferenceSingleton<PlayerDiceHandHolder>.Instance.RemoveDiceFromHand(diceInstance);
			diceInstance.StoreDiceInstance();
		}
		PlaySFX();
		targetToPurifyLogic.ActivateOmen(purifyAction, amount, null, source);
		if (flag)
		{
			for (int j = 0; j < paralyzedHexDieAdditionalTimes; j++)
			{
				targetToPurifyLogic.ActivateOmen(purifyAction, amount, null, source);
			}
		}
		ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsEffectActiveWithActivation(moonlightEffect, activateFeedback: false);
		SpawnVFXOnPlayerPosition(4f);
	}
}
